changeSet.sql:

ALTER TABLE rule ADD COLUMN IF NOT EXISTS checklist_key TEXT;
ALTER TABLE rule ADD COLUMN IF NOT EXISTS checklist_doi TEXT;

COMMENT ON COLUMN rule.checklist_key IS 'UUID of the GBIF checklist dataset that the taxon refers to (e.g., COL XR 7ddf754f-d193-4cc9-b351-99906754a03b).';
COMMENT ON COLUMN rule.checklist_doi IS 'DOI of the GBIF checklist dataset (e.g., 10.48580/dgykv).';
